#!/usr/bin/env node
/**
 * Makes the sample files for /dev/blocks in public/dev/samples/ (docs/V3_PLAN.md 5.7: fixtures
 * generated by script, abstract shapes, a test tone, no third-party samples). Nothing here shows
 * the owner's hardware, people, or results. The folder and this page are removed before release.
 *
 * It also writes the audio samples' waveforms to app/(site)/dev/blocks/sample-peaks.json: peak
 * levels computed here, once, as the admin will compute them at upload (ARCHITECTURE.md 13A), so
 * the samples page draws real waveforms and no visitor's browser decodes a file to draw one.
 *
 * Needs ffmpeg on the PATH and Google Chrome (or CHROME_PATH) for the PDF.
 *   node scripts/make-samples.mjs           every sample file, and the waveforms
 *   node scripts/make-samples.mjs --peaks   only the waveforms, from the audio files already there
 *   node scripts/make-samples.mjs --docx    only the Word sample (JSZip stamps times, so the
 *                                           other files would change if they were rewritten)
 */
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import JSZip from 'jszip';
import { chromium } from '@playwright/test';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const out = path.join(root, 'public', 'dev', 'samples');
fs.mkdirSync(out, { recursive: true });
const at = (name) => path.join(out, name);

function ffmpeg(args) {
  execFileSync('ffmpeg', ['-hide_banner', '-loglevel', 'error', '-y', ...args], { stdio: 'inherit' });
}

// ---------------------------------------------------------------------------------------------
// The audio samples' waveforms: peak levels from 0 to 1, stored next to the samples page
// ---------------------------------------------------------------------------------------------
const PEAKS_FILE = path.join(root, 'app', '(site)', 'dev', 'blocks', 'sample-peaks.json');
const PEAK_COUNT = 360;
const AUDIO_SAMPLES = ['tone.mp3', 'tone-long.mp3'];

/** Decodes a file to mono 32-bit samples at 8 kHz and returns its peaks, the loudest at 1. */
function peaksOf(file) {
  const raw = execFileSync(
    'ffmpeg',
    ['-hide_banner', '-loglevel', 'error', '-i', file, '-ac', '1', '-ar', '8000', '-f', 'f32le', 'pipe:1'],
    { maxBuffer: 1 << 28 },
  );
  const samples = new Float32Array(raw.buffer.slice(raw.byteOffset, raw.byteOffset + raw.byteLength - (raw.byteLength % 4)));
  if (samples.length === 0) throw new Error(`No audio decoded from ${file}`);
  const buckets = Math.min(PEAK_COUNT, samples.length);
  const peaks = [];
  let loudest = 0;
  for (let b = 0; b < buckets; b += 1) {
    const start = Math.floor((b * samples.length) / buckets);
    const end = Math.max(start + 1, Math.floor(((b + 1) * samples.length) / buckets));
    let peak = 0;
    for (let i = start; i < end; i += 1) peak = Math.max(peak, Math.abs(samples[i]));
    peaks.push(peak);
    loudest = Math.max(loudest, peak);
  }
  return peaks.map((peak) => (loudest > 0 ? Math.min(1, Math.round((peak / loudest) * 1000) / 1000) : 0));
}

function writeSamplePeaks() {
  const lines = AUDIO_SAMPLES.map((name) => `  ${JSON.stringify(name)}: ${JSON.stringify(peaksOf(at(name)))}`);
  fs.writeFileSync(PEAKS_FILE, ['{', lines.join(',\n'), '}', ''].join('\n'));
  console.log(`${path.relative(root, PEAKS_FILE)}: ${PEAK_COUNT} peaks for ${AUDIO_SAMPLES.join(', ')}`);
}

if (process.argv.includes('--peaks')) {
  writeSamplePeaks();
  process.exit(0);
}

if (process.argv.includes('--docx')) {
  await makeDocx();
  console.log('public/dev/samples/document.docx: rewritten');
  process.exit(0);
}

