// ---------------------------------------------------------------------------------------------
// A drawing for pan and zoom
// ---------------------------------------------------------------------------------------------
function drawingSvg() {
  const W = 2400;
  const H = 1600;
  const lines = [];
  for (let x = 0; x <= W; x += 40) lines.push(`<line x1="${x}" y1="0" x2="${x}" y2="${H}" stroke="#1557c0" stroke-opacity="${x % 200 === 0 ? 0.35 : 0.12}" stroke-width="1"/>`);
  for (let y = 0; y <= H; y += 40) lines.push(`<line x1="0" y1="${y}" x2="${W}" y2="${y}" stroke="#1557c0" stroke-opacity="${y % 200 === 0 ? 0.35 : 0.12}" stroke-width="1"/>`);
  const circles = [];
  for (let r = 60; r <= 600; r += 60) circles.push(`<circle cx="1200" cy="800" r="${r}" fill="none" stroke="#0b1f45" stroke-width="${r % 180 === 0 ? 3 : 1.5}"/>`);
  const labels = [];
  const zones = 'ABCDEF';
  for (let i = 0; i < 6; i += 1) {
    for (let j = 0; j < 8; j += 1) {
      labels.push(`<text x="${j * 300 + 150}" y="${i * 266 + 140}" font-family="monospace" font-size="18" text-anchor="middle" fill="#34496e">${zones[i]}${j + 1}</text>`);
    }
  }
  const fine = [];
  for (let k = 0; k < 12; k += 1) {
    fine.push(`<text x="1200" y="${770 + k * 6}" font-family="monospace" font-size="4" text-anchor="middle" fill="#0b1f45">Fine print line ${k + 1}: zoom in to read it.</text>`);
  }
  return `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">
<rect width="${W}" height="${H}" fill="#f4f7fb"/>
${lines.join('\n')}
${circles.join('\n')}
<rect x="40" y="40" width="${W - 80}" height="${H - 80}" fill="none" stroke="#0b1f45" stroke-width="4"/>
<path d="M200 1400 L700 900 L1100 1100 L1600 500 L2200 700" fill="none" stroke="#c2410c" stroke-width="5"/>
${labels.join('\n')}
${fine.join('\n')}
<text x="80" y="1540" font-family="sans-serif" font-size="28" fill="#0b1f45">Sample drawing for the pan and zoom viewer</text>
</svg>
`;
}
fs.writeFileSync(at('drawing.svg'), drawingSvg());

