// ---------------------------------------------------------------------------------------------
// A Word document
// ---------------------------------------------------------------------------------------------
async function makeDocx() {
  const zip = new JSZip();
  const W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main';
  zip.file(
    '[Content_Types].xml',
    `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
<Default Extension="xml" ContentType="application/xml"/>
<Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>
<Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/>
</Types>`,
  );
  zip.file(
    '_rels/.rels',
    `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>
</Relationships>`,
  );
  zip.file(
    'word/_rels/document.xml.rels',
    `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>
</Relationships>`,
  );
  zip.file(
    'word/styles.xml',
    `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:styles xmlns:w="${W}">
<w:style w:type="paragraph" w:default="1" w:styleId="Normal"><w:name w:val="Normal"/><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:sz w:val="22"/></w:rPr><w:pPr><w:spacing w:after="160"/></w:pPr></w:style>
<w:style w:type="paragraph" w:styleId="Heading1"><w:name w:val="heading 1"/><w:basedOn w:val="Normal"/><w:pPr><w:spacing w:before="240" w:after="120"/></w:pPr><w:rPr><w:b/><w:color w:val="0B1F45"/><w:sz w:val="36"/></w:rPr></w:style>
<w:style w:type="paragraph" w:styleId="Heading2"><w:name w:val="heading 2"/><w:basedOn w:val="Normal"/><w:pPr><w:spacing w:before="200" w:after="100"/></w:pPr><w:rPr><w:b/><w:color w:val="1557C0"/><w:sz w:val="28"/></w:rPr></w:style>
</w:styles>`,
  );
  const p = (text, style) =>
    `<w:p>${style ? `<w:pPr><w:pStyle w:val="${style}"/></w:pPr>` : ''}<w:r><w:t xml:space="preserve">${text}</w:t></w:r></w:p>`;
  const cell = (text, bold) =>
    `<w:tc><w:tcPr><w:tcW w:w="4500" w:type="dxa"/></w:tcPr><w:p><w:r>${bold ? '<w:rPr><w:b/></w:rPr>' : ''}<w:t>${text}</w:t></w:r></w:p></w:tc>`;
  const row = (a, b, bold) => `<w:tr>${cell(a, bold)}${cell(b, bold)}</w:tr>`;
  // An explicit page break: the reader shows one page per break (docx-preview breakPages).
  const pageBreak = '<w:p><w:r><w:br w:type="page"/></w:r></w:p>';
  const borders = ['top', 'left', 'bottom', 'right', 'insideH', 'insideV'].map((side) => `<w:${side} w:val="single" w:sz="4" w:color="8090A8"/>`).join('');
  const body = [
    p('Sample Word document', 'Heading1'),
    p('This file tests the Word reader on the samples page. It renders inside an isolated frame, so nothing in the file can reach the page around it.'),
    `<w:p><w:r><w:t xml:space="preserve">A paragraph with </w:t></w:r><w:r><w:rPr><w:b/></w:rPr><w:t>bold</w:t></w:r><w:r><w:t xml:space="preserve"> and </w:t></w:r><w:r><w:rPr><w:i/></w:rPr><w:t>italic</w:t></w:r><w:r><w:t xml:space="preserve"> text.</w:t></w:r></w:p>`,
    p('A table', 'Heading2'),
    `<w:tbl><w:tblPr><w:tblW w:w="9000" w:type="dxa"/><w:tblBorders>${borders}</w:tblBorders></w:tblPr><w:tblGrid><w:gridCol w:w="4500"/><w:gridCol w:w="4500"/></w:tblGrid>${row('Column one', 'Column two', true)}${row('Row one', 'Value one')}${row('Row two', 'Value two')}${row('Row three', 'Value three')}</w:tbl>`,
    pageBreak,
    p('Page two', 'Heading1'),
    p('Each page break in the file starts a new page in the reader, so the page control can move between the pages.'),
    p('Search the reader for a word, such as the word reader, and step through the matches with the arrows.'),
    pageBreak,
    p('Page three', 'Heading1'),
    p('The download link beside the reader offers the original file.'),
  ].join('');
  zip.file(
    'word/document.xml',
    `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:document xmlns:w="${W}"><w:body>${body}<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440"/></w:sectPr></w:body></w:document>`,
  );
  const buffer = await zip.generateAsync({ type: 'nodebuffer', compression: 'DEFLATE' });
  fs.writeFileSync(at('document.docx'), buffer);
}
await makeDocx();

// ---------------------------------------------------------------------------------------------
// A 3D model: four named parts, so the exploded view and the parts list have something to show
// ---------------------------------------------------------------------------------------------
function box(w, h, d) {
  const x = w / 2;
  const y = h / 2;
  const z = d / 2;
  const faces = [
    { n: [1, 0, 0], v: [[x, -y, z], [x, -y, -z], [x, y, -z], [x, y, z]] },
    { n: [-1, 0, 0], v: [[-x, -y, -z], [-x, -y, z], [-x, y, z], [-x, y, -z]] },
    { n: [0, 1, 0], v: [[-x, y, z], [x, y, z], [x, y, -z], [-x, y, -z]] },
    { n: [0, -1, 0], v: [[-x, -y, -z], [x, -y, -z], [x, -y, z], [-x, -y, z]] },
    { n: [0, 0, 1], v: [[-x, -y, z], [x, -y, z], [x, y, z], [-x, y, z]] },
    { n: [0, 0, -1], v: [[x, -y, -z], [-x, -y, -z], [-x, y, -z], [x, y, -z]] },
  ];
  const positions = [];
  const normals = [];
  const indices = [];
  faces.forEach((face, f) => {
    face.v.forEach((v) => {
      positions.push(...v);
      normals.push(...face.n);
    });
    const o = f * 4;
    indices.push(o, o + 1, o + 2, o, o + 2, o + 3);
  });
  return { positions, normals, indices };
}

function cylinder(r, h, segments = 40) {
  const positions = [];
  const normals = [];
  const indices = [];
  for (let i = 0; i <= segments; i += 1) {
    const a = (i / segments) * Math.PI * 2;
    const c = Math.cos(a);
    const s = Math.sin(a);
    positions.push(r * c, -h / 2, r * s, r * c, h / 2, r * s);
    normals.push(c, 0, s, c, 0, s);
  }
  for (let i = 0; i < segments; i += 1) {
    const a = i * 2;
    indices.push(a, a + 1, a + 3, a, a + 3, a + 2);
  }
  for (const [y, ny] of [[h / 2, 1], [-h / 2, -1]]) {
    const center = positions.length / 3;
    positions.push(0, y, 0);
    normals.push(0, ny, 0);
    for (let i = 0; i <= segments; i += 1) {
      const a = (i / segments) * Math.PI * 2;
      positions.push(r * Math.cos(a), y, r * Math.sin(a));
      normals.push(0, ny, 0);
    }
    for (let i = 0; i < segments; i += 1) {
      if (ny > 0) indices.push(center, center + i + 2, center + i + 1);
      else indices.push(center, center + i + 1, center + i + 2);
    }
  }
  return { positions, normals, indices };
}

function torus(R, r, radial = 20, tubular = 64) {
  const positions = [];
  const normals = [];
  const indices = [];
  for (let j = 0; j <= radial; j += 1) {
    for (let i = 0; i <= tubular; i += 1) {
      const u = (i / tubular) * Math.PI * 2;
      const v = (j / radial) * Math.PI * 2;
      const cx = R * Math.cos(u);
      const cz = R * Math.sin(u);
      const x = (R + r * Math.cos(v)) * Math.cos(u);
      const y = r * Math.sin(v);
      const z = (R + r * Math.cos(v)) * Math.sin(u);
      positions.push(x, y, z);
      const nx = x - cx;
      const nz = z - cz;
      const len = Math.hypot(nx, y, nz) || 1;
      normals.push(nx / len, y / len, nz / len);
    }
  }
  for (let j = 1; j <= radial; j += 1) {
    for (let i = 1; i <= tubular; i += 1) {
      const a = (tubular + 1) * j + i - 1;
      const b = (tubular + 1) * (j - 1) + i - 1;
      const c = (tubular + 1) * (j - 1) + i;
      const d = (tubular + 1) * j + i;
      // Outward-facing triangles (this torus lies in the x-z plane).
      indices.push(a, d, b, b, d, c);
    }
  }
  return { positions, normals, indices };
}

function sphere(r, widthSegments = 40, heightSegments = 24) {
  const positions = [];
  const normals = [];
  const indices = [];
  for (let iy = 0; iy <= heightSegments; iy += 1) {
    const v = iy / heightSegments;
    for (let ix = 0; ix <= widthSegments; ix += 1) {
      const u = ix / widthSegments;
      const x = -Math.cos(u * Math.PI * 2) * Math.sin(v * Math.PI);
      const y = Math.cos(v * Math.PI);
      const z = Math.sin(u * Math.PI * 2) * Math.sin(v * Math.PI);
      positions.push(r * x, r * y, r * z);
      normals.push(x, y, z);
    }
  }
  for (let iy = 0; iy < heightSegments; iy += 1) {
    for (let ix = 0; ix < widthSegments; ix += 1) {
      const a = iy * (widthSegments + 1) + ix + 1;
      const b = iy * (widthSegments + 1) + ix;
      const c = (iy + 1) * (widthSegments + 1) + ix;
      const d = (iy + 1) * (widthSegments + 1) + ix + 1;
      if (iy !== 0) indices.push(a, b, d);
      if (iy !== heightSegments - 1) indices.push(b, c, d);
    }
  }
  return { positions, normals, indices };
}

function makeGlb() {
  const parts = [
    { name: 'Base', geo: box(2.0, 0.2, 1.4), t: [0, 0.1, 0], color: [0.55, 0.58, 0.62, 1], metallic: 0.85, roughness: 0.35 },
    { name: 'Column', geo: cylinder(0.22, 1.2), t: [0, 0.8, 0], color: [0.12, 0.14, 0.18, 1], metallic: 0.2, roughness: 0.55 },
    { name: 'Ring', geo: torus(0.5, 0.07), t: [0, 1.15, 0], color: [0.9, 0.42, 0.12, 1], metallic: 0.1, roughness: 0.45 },
    { name: 'Cap', geo: sphere(0.3), t: [0, 1.62, 0], color: [0.85, 0.88, 0.92, 1], metallic: 0.05, roughness: 0.25 },
  ];
  const chunks = [];
  let offset = 0;
  const bufferViews = [];
  const accessors = [];
  const push = (typed, target) => {
    const bytes = Buffer.from(typed.buffer, typed.byteOffset, typed.byteLength);
    const padding = (4 - (bytes.length % 4)) % 4;
    bufferViews.push({ buffer: 0, byteOffset: offset, byteLength: bytes.length, target });
    chunks.push(bytes, Buffer.alloc(padding));
    offset += bytes.length + padding;
    return bufferViews.length - 1;
  };
  const meshes = parts.map((part, i) => {
    const pos = new Float32Array(part.geo.positions);
    const nor = new Float32Array(part.geo.normals);
    const idx = new Uint16Array(part.geo.indices);
    const min = [Infinity, Infinity, Infinity];
    const max = [-Infinity, -Infinity, -Infinity];
    for (let k = 0; k < pos.length; k += 3) {
      for (let a = 0; a < 3; a += 1) {
        min[a] = Math.min(min[a], pos[k + a]);
        max[a] = Math.max(max[a], pos[k + a]);
      }
    }
    accessors.push({ bufferView: push(pos, 34962), componentType: 5126, count: pos.length / 3, type: 'VEC3', min, max });
    const posAccessor = accessors.length - 1;
    accessors.push({ bufferView: push(nor, 34962), componentType: 5126, count: nor.length / 3, type: 'VEC3' });
    const norAccessor = accessors.length - 1;
    accessors.push({ bufferView: push(idx, 34963), componentType: 5123, count: idx.length, type: 'SCALAR' });
    const idxAccessor = accessors.length - 1;
    return { name: part.name, primitives: [{ attributes: { POSITION: posAccessor, NORMAL: norAccessor }, indices: idxAccessor, material: i }] };
  });
  const gltf = {
    asset: { version: '2.0', generator: 'make-samples.mjs' },
    scene: 0,
    scenes: [{ name: 'Sample', nodes: [0] }],
    nodes: [
      { name: 'Sample assembly', children: parts.map((_, i) => i + 1) },
      ...parts.map((part, i) => ({ name: part.name, mesh: i, translation: part.t })),
    ],
    meshes,
    materials: parts.map((part) => ({
      name: `${part.name} material`,
      pbrMetallicRoughness: { baseColorFactor: part.color, metallicFactor: part.metallic, roughnessFactor: part.roughness },
    })),
    accessors,
    bufferViews,
    buffers: [{ byteLength: offset }],
  };
  const bin = Buffer.concat(chunks);
  let json = Buffer.from(JSON.stringify(gltf), 'utf8');
  json = Buffer.concat([json, Buffer.alloc((4 - (json.length % 4)) % 4, 0x20)]);
  const header = Buffer.alloc(12);
  const total = 12 + 8 + json.length + 8 + bin.length;
  header.writeUInt32LE(0x46546c67, 0);
  header.writeUInt32LE(2, 4);
  header.writeUInt32LE(total, 8);
  const jsonHeader = Buffer.alloc(8);
  jsonHeader.writeUInt32LE(json.length, 0);
  jsonHeader.writeUInt32LE(0x4e4f534a, 4);
  const binHeader = Buffer.alloc(8);
  binHeader.writeUInt32LE(bin.length, 0);
  binHeader.writeUInt32LE(0x004e4942, 4);
  fs.writeFileSync(at('model.glb'), Buffer.concat([header, jsonHeader, json, binHeader, bin]));
}
makeGlb();

// ---------------------------------------------------------------------------------------------
// A three-page PDF with real text (searchable), and its first page as the poster
// ---------------------------------------------------------------------------------------------
async function makePdf() {
  const page = (n, body) => `<section class="page"><h1>Sample document</h1><p class="meta">Page ${n} of 3</p>${body}</section>`;
  const html = `<!doctype html><html><head><meta charset="utf-8"><style>
    @page { size: A4; margin: 0; }
    body { margin: 0; font-family: Arial, sans-serif; color: #0b1f45; }
    .page { width: 210mm; height: 297mm; box-sizing: border-box; padding: 24mm; page-break-after: always; position: relative;
      background-image: linear-gradient(rgba(21,87,192,0.08) 1px, transparent 1px), linear-gradient(90deg, rgba(21,87,192,0.08) 1px, transparent 1px);
      background-size: 8mm 8mm; }
    h1 { font-size: 26pt; margin: 0 0 4mm; }
    h2 { font-size: 15pt; margin: 10mm 0 3mm; color: #1557c0; }
    p { font-size: 11pt; line-height: 1.6; margin: 0 0 4mm; max-width: 150mm; }
    .meta { color: #5b6e90; font-family: monospace; }
    table { border-collapse: collapse; font-size: 10.5pt; margin-top: 4mm; }
    td, th { border: 1px solid #8090a8; padding: 2mm 4mm; text-align: left; }
    .shape { position: absolute; right: 24mm; bottom: 24mm; width: 60mm; height: 60mm; border: 2px solid #1557c0; border-radius: 50%; }
  </style></head><body>
    ${page(1, '<p>This file tests the document reader on the samples page. Try the page buttons, the zoom buttons, and the search box: search for the word viewer to find each match.</p><h2>What the reader does</h2><p>The reader paints this first page as a poster, then loads its engine only when the reader comes into view, or on a tap on a phone. A plain download link sits beside it.</p><div class="shape"></div>')}
    ${page(2, '<h2>A table</h2><table><tr><th>Item</th><th>Value</th></tr><tr><td>First row</td><td>1</td></tr><tr><td>Second row</td><td>2</td></tr><tr><td>Third row</td><td>3</td></tr></table><h2>Search</h2><p>The word viewer appears again on this page, so the search has more than one match to step through.</p>')}
    ${page(3, '<h2>Last page</h2><p>This is the last page of the sample. The viewer should stop at page 3 of 3 when you turn forward.</p>')}
  </body></html>`;
  const browser = await chromium.launch(process.env.CHROME_PATH ? { executablePath: process.env.CHROME_PATH } : { channel: 'chrome' });
  try {
    const tab = await browser.newPage({ viewport: { width: 794, height: 1123 }, deviceScaleFactor: 1 });
    await tab.setContent(html, { waitUntil: 'load' });
    await tab.pdf({ path: at('document.pdf'), format: 'A4', printBackground: true, preferCSSPageSize: true });
    await tab.screenshot({ path: at('document-poster.png'), clip: { x: 0, y: 0, width: 794, height: 1123 } });
    const drawingTab = await browser.newPage({ viewport: { width: 2400, height: 1600 }, deviceScaleFactor: 1 });
    await drawingTab.setContent(`<!doctype html><html><body style="margin:0">${drawingSvg()}</body></html>`);
    await drawingTab.screenshot({ path: at('drawing.png'), clip: { x: 0, y: 0, width: 2400, height: 1600 } });
  } finally {
    await browser.close();
  }
  ffmpeg(['-i', at('document-poster.png'), '-vf', 'scale=794:-1', '-c:v', 'libwebp', '-quality', '80', at('document-poster.webp')]);
  fs.rmSync(at('document-poster.png'));
}
await makePdf();

for (const name of fs.readdirSync(out).sort()) {
  console.log(`${name.padEnd(24)} ${fs.statSync(at(name)).size} bytes`);
}
